import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        Map<Long, Long> freq = new HashMap<>();
        long count = 0;
        for (int i = 0; i < n; i++) {
            long x = sc.nextLong();
            count += freq.getOrDefault(k - x, 0L);
            freq.put(x, freq.getOrDefault(x, 0L) + 1L);
        }
        System.out.println(count);
    }
}

