import sys
from collections import Counter

s = sys.stdin.readline().rstrip('\r\n')
cnt = Counter(s)
for i, ch in enumerate(s):
    if cnt[ch] == 1:
        print(f'{i} {ch}')
        break
else:
    print(-1)
